insert into public.web_content (page, content)
select 'legal', $web${"terms":{"title":"Terms & Conditions","updated":"Last updated: May 1, 2026 · City Government of Dasmariñas · Apoyo web portal","secondaryLinkLabel":"Privacy Policy","secondaryLinkTo":"/privacy","sections":[{"heading":"1. Agreement","body":"By accessing or using this website and any related online services that reference these Terms (collectively, the \"Services\"), you agree to be bound by these Terms & Conditions. If you do not agree, please discontinue use of the Services."},{"heading":"2. Role of the Services","body":"Apoyo and this portal are operated to support public information and access related to social welfare programs administered or coordinated by the City Government of Dasmariñas, including through the City Social Welfare and Development Office (\"CSWDO\"). The Services may include descriptions of programs, downloadable materials, contact information, and links to official channels."},{"heading":"3. Not a guarantee of benefits","body":"Information on the Services is provided for general guidance. Approval of assistance, eligibility, funding availability, timelines, and required documents are determined solely in accordance with applicable city ordinances, administrative issuances, and CSWDO assessment procedures. Nothing on this site constitutes a promise or guarantee of assistance."},{"heading":"4. Accurate information","body":"You agree not to submit false, misleading, or fraudulent information through any web forms, email, or attachments connected with the Services. The City may decline to process requests that appear incomplete, inconsistent with supporting documents, or fraudulent."},{"heading":"5. Official records","body":"In case of discrepancy between information published online and records maintained by the City or CSWDO, the latter prevails unless formally corrected through official channels."},{"heading":"6. Intellectual property","body":"City seals, logos, marks, and other official insignia displayed on the Services remain the property of the City Government of Dasmariñas or their respective rights holders. Unauthorised commercial use, modification, or misrepresentation is prohibited."},{"heading":"7. Third-party links","body":"The Services may link to third-party websites (for example, social media or messaging platforms). Those sites have their own terms and privacy practices; the City is not responsible for their content or handling of personal data once you leave this portal."},{"heading":"8. Limitation of liability","body":"To the fullest extent permitted by applicable law, the City Government of Dasmariñas and its officers and employees shall not be liable for any indirect, incidental, special, or consequential damages arising from use of the Services, including interruptions, inaccuracies in unofficial copies of forms, or reliance on summaries posted online."},{"heading":"9. Changes","body":"These Terms may be updated from time to time. The \"Last updated\" date above will be revised when material changes are posted. Continued use after updates constitutes acceptance of the revised Terms."},{"heading":"10. Contact","body":"For questions about these Terms or Apoyo, contact the City Government of Dasmariñas through the official channels listed on this website (including CSWDO and the Office of the City Mayor). Telephone: (046) 481 4600 local 680 (verify current trunkline and local extensions with the City telephone directory)."},{"heading":"11. Governing law","body":"These Terms are governed by the laws of the Republic of the Philippines. Appropriate venues shall be as provided under applicable rules."}]},"privacy":{"title":"Privacy Policy","updated":"Last updated: May 1, 2026 · City Government of Dasmariñas · Apoyo web portal","secondaryLinkLabel":"Terms & Conditions","secondaryLinkTo":"/terms","sections":[{"heading":"1. Purpose","body":"This Privacy Policy explains how personal information may be collected, used, stored, and protected when you interact with the Apoyo website and related official channels of the City Government of Dasmariñas, particularly programs coordinated through CSWDO. It is intended to align with the Data Privacy Act of 2012 (Republic Act No. 10173) and implementing rules."},{"heading":"2. Personal Information Controller","body":"The City Government of Dasmariñas acts as a personal information controller for personal data processed for legitimate governmental purposes. Specific offices (such as CSWDO) may process data according to their mandates and applicable memoranda."},{"heading":"3. Information we may collect","body":"Depending on how you engage with us, this may include:\n- Identity and contact details (name, address, phone number, email)\n- Program-related information submitted with applications (for example, household details, medical or financial circumstances as required by forms)\n- Technical information typical of website visits (such as browser type, approximate region, and timestamps), used mainly for security and troubleshooting when server logs are retained"},{"heading":"4. How we use information","body":"Personal information may be processed to:\n- Respond to inquiries and route requests to the correct office\n- Evaluate eligibility and administer assistance programs\n- Comply with legal obligations and legitimate auditing requirements\n- Maintain the security and integrity of digital services"},{"heading":"5. Legal bases","body":"Processing may rely on consent where required, performance of a contract or undertaking at your request, compliance with law, or legitimate interests of the City consistent with data privacy principles (lawfulness, proportionality, transparency)."},{"heading":"6. Sharing and disclosure","body":"Personal information may be shared only when necessary and lawful—for example, with other city departments involved in service delivery, with regulators when mandated by law, or with service providers bound by confidentiality obligations assisting IT operations. We do not sell personal data."},{"heading":"7. Retention","body":"Records are retained according to applicable archiving rules, program guidelines, and audit requirements. When retention periods expire, data shall be disposed of securely as policies allow."},{"heading":"8. Security","body":"The City employs reasonable organisational and technical safeguards appropriate to the risks involved. No online transmission is completely risk-free; users should protect account credentials and devices."},{"heading":"9. Your rights","body":"Subject to applicable law, data subjects may have rights including reasonable access to certain personal data, correction of inaccurate entries, and objection or withdrawal of consent where processing is consent-based, among others provided under RA 10173.\n\nTo exercise rights or raise privacy concerns, contact the City through official channels listed on this website or its designated Data Protection Officer when published by the City."},{"heading":"10. Cookies & similar technologies","body":"If this site uses cookies or local storage for basic functionality or analytics, use will be proportionate to operational needs. You may control cookies through your browser settings; disabling some cookies may limit features."},{"heading":"11. Updates","body":"This Privacy Policy may be revised to reflect legal requirements or changes in City practices. Material updates will be indicated by revising the \"Last updated\" date above."},{"heading":"12. Contact","body":"City Government of Dasmariñas · CSWDO / Office of the City Mayor (as applicable). Email (where officially used): officeofthecitymayordc@gmail.com · Telephone: (046) 481 4600 local 680 (verify current listings)."}]}}$web$::jsonb
where not exists (select 1 from public.web_content where page = 'legal');

