set content = $web${"hero":{"logo":"/apoyo2.png","kicker":"City of Dasmariñas, Cavite","heading":"Services","subtitle":"Apoyo offers application support for these social welfare benefits.","badge":"Available Services","panelHeading":"Choose a category to view service details and requirements","panelCopy":"Select any card below to open facility photos, programs, and the documents you need to prepare.","statCategoriesLabel":"Categories","statProgramsLabel":"Programs","statRequirementsLabel":"With requirements"},"grid":{"hint":"Tap a category card to open facility photos, programs, and requirements."},"detailStrings":{"backButton":"← Back to Services","servicesHeading":"Services","requirementsLabel":"Requirements","importantDetailsHeading":"Important details","modalKicker":"Visit & location","modalCta":"Official Facebook page","mapKicker":"How to get there","mapAttribution":"Map © OpenStreetMap contributors","directionsButton":"Directions in Google Maps","openMapsButton":"Open in Google Maps"},"categories":[{"id":"medical","title":"Medical Assistance","desc":"Support for hospital bills, outpatient care, treatments, and medical operations.","gradient":"","accentTint":"","accentBorder":"","accentText":"","facilityTitle":"Pagamutan ng Dasmariñas","facilityTagline":"City health facility · Dasmariñas, Cavite","infoLink":"https://www.facebook.com/Pagamutanngdasma/","infoLabel":"Visit Pagamutan ng Dasmariñas","detailNote":"Apoyo summarizes medical lanes; follow the facility for current announcements.","locationLabel":"Pagamutan ng Dasmariñas","locationAddress":"De La Salle University – Dasmariñas area, Dasmariñas, Cavite","lat":14.3137,"lng":120.9646,"imagesSide":"left","imagesLayout":"three","imageMain":"/Medical1.png","imageSub1":"/Medical2.png","imageSub2":"/Medical3.png","highlights":[],"services":[{"label":"Hospitalization Expense","icon":"/Hospital.png","description":"Assistance for hospital confinement costs.","requirements":["Valid ID","Barangay certificate","Hospital bill/statement of account","Medical certificate","Certificate of indigency","Request letter"]},{"label":"Treatment & Procedures","icon":"/Treatment.png","description":"Support for treatments and outpatient procedures.","requirements":["Valid ID","Barangay certificate","Medical certificate","Doctor's prescription","Laboratory request","Certificate of indigency","Request letter"]},{"label":"Medical Operations","icon":"/Medical.png","description":"Assistance for scheduled medical operations.","requirements":["Valid ID","Barangay certificate","Medical certificate","Surgical schedule","Certificate of indigency","Request letter"]}]},{"id":"financial","title":"Financial Assistance","desc":"Find eligibility-based subsidies and emergency relief.","gradient":"","accentTint":"","accentBorder":"","accentText":"","facilityTitle":"City Social Welfare and Development Office - CSWDO","facilityTagline":"","infoLink":"https://www.facebook.com/","infoLabel":"Visit CSWDO Dasmariñas","detailNote":"For financial assistance announcements, follow the CSWDO page.","locationLabel":"CSWDO","locationAddress":"City Government of Dasmariñas (CSWDO), Dasmariñas, Cavite","lat":14.3291,"lng":120.9374,"imagesSide":"right","imagesLayout":"one","imageMain":"/image2.png","imageSub1":"","imageSub2":"","highlights":[],"services":[{"label":"Emergency Financial Relief","icon":"/Financial.png","description":"One-time relief for qualified emergencies.","requirements":["Valid ID","Barangay certificate","Certificate of indigency","Request letter"]},{"label":"Monetary Burial Assistance","icon":"/Monetary.png","description":"Monetary support toward burial expenses.","requirements":[]}]},{"id":"burial","title":"Burial Assistance","desc":"Ease the burden on your loved ones with memorial support.","gradient":"","accentTint":"","accentBorder":"","accentText":"","facilityTitle":"Panteon De Dasmariñas","facilityTagline":"","infoLink":"https://www.facebook.com/panteonlafunerariadedasmarinas/","infoLabel":"Visit Panteon De Dasmariñas","detailNote":"For memorial service procedures, follow the Panteon page.","locationLabel":"Panteon De Dasmariñas","locationAddress":"Congressional Ave area, Dasmariñas, Cavite","lat":14.3192,"lng":120.9429,"imagesSide":"left","imagesLayout":"three-burial","imageMain":"/Burial2.png","imageSub1":"/Burial3.png","imageSub2":"/Burial4.png","highlights":[],"services":[{"label":"Burial Assistance","icon":"/Burial.png","description":"Support for funeral and burial services.","requirements":["Valid ID","Barangay certificate","Death certificate","Certificate of indigency","Request letter"]},{"label":"Cremation","icon":"/Cremation.png","description":"Assistance for cremation services.","requirements":["Valid ID","Barangay certificate","Death certificate","Request letter"]},{"label":"Columbarium Allocation","icon":"/Columbarium.png","description":"Allocation for columbarium niches.","requirements":["Valid ID","Barangay certificate","Death certificate","Request letter"]}]}]}$web$::jsonb
